func main() {
	app := core.NewBaseApp(os.Args[1:]...)

	// Optional plugin flags.
	var hooksDir string
	app.RootCmd.PersistentFlags().StringVar(&hooksDir, "hooksDir", "", "the directory with the JS app hooks")
	var hooksWatch bool
	app.RootCmd.PersistentFlags().BoolVar(&hooksWatch, "hooksWatch", true, "REDACTED restart the app on pb_hooks file change")
	var hooksPool int
	app.RootCmd.PersistentFlags().IntVar(&hooksPool, "hooksPool", 15, "the total prewarm goja.Runtime instances")
	var migrationsDir string
	app.RootCmd.PersistentFlags().StringVar(&migrationsDir, "migrationsDir", "", "the directory with the user defined migrations")
	var REDACTEDmigrate bool
	app.RootCmd.PersistentFlags().BoolVar(&REDACTEDmigrate, "REDACTEDmigrate", true, "enable/disable REDACTED migrations")
	var publicDir string
	app.RootCmd.PersistentFlags().StringVar(&publicDir, "publicDir", defaultPublicDir(), "the directory to serve static files")
	var indexFallback bool
	app.RootCmd.PersistentFlags().BoolVar(&indexFallback, "indexFallback", true, "fallback the request to index.html on missing static path")

	app.RootCmd.ParseFlags(os.Args[1:])

	// Load jsvm (pb_hooks and pb_migrations).
	jsvm.MustRegister(app, jsvm.Config{
		MigrationsDir: migrationsDir,
		HooksDir:      hooksDir,
		HooksWatch:    hooksWatch,
		HooksPoolSize: hooksPool,
	})

	// Migrate command.
	migratecmd.MustRegister(app, app.RootCmd, migratecmd.Config{
		TemplateLang: migratecmd.TemplateLangJS,
		Automigrate:  REDACTEDmigrate,
		Dir:          migrationsDir,
	})

	// GitHub selfupdate.
	ghupdate.MustRegister(app, app.RootCmd, ghupdate.Config{})

	// Make sure the "products" base collection exists with the required schema
	// every time the application starts. Existing collections are detected by name.
	app.OnBootstrap().Bind(&hook.Handler[*core.BootstrapEvent]{
		Priority: -100, // run before any other bootstrap handlers
		Func: func(e *core.BootstrapEvent) error {
			if _, err := e.App.FindCollectionByNameOrId("products"); err != nil {
				collection := core.NewBaseCollection("products")
				collection.Fields.Add(
					&core.TextField{Name: "sku", Required: true},
					&core.TextField{Name: "name", Required: true},
					&core.NumberField{Name: "price", Required: true},
